// src/main.js
import { createApp } from "vue";
import App from "./App.vue";
import router from "./router";
import userStore from "@/stores/userStore"; // 导入 Vuex userStore
import productStore from "@/stores/productStore"; // 引入 productStore
import ElementPlus from "element-plus"; // Element Plus 全量引入
import "element-plus/dist/index.css"; // 引入 Element Plus 样式

// Element Plus 中文语言包
import zhCn from "element-plus/es/locale/lang/zh-cn";

// 图标
import * as ElementPlusIconsVue from "@element-plus/icons-vue";
import { createStore } from "vuex"; // 创建 Vuex

// 创建 Vuex store
const store = createStore({
  modules: {
    user: userStore, // 加载 userStore
    product: productStore, // 加载 productStore
  },
});

// 创建 Vue 应用
const app = createApp(App);

// 在应用创建时初始化用户状态
store.commit("user/initializeUser"); // 使用 store 的模块化调用方法

// 注册全局应用
app.use(router); // 路由
app.use(store); // 注册 Vuex store
app.use(ElementPlus, {
  locale: zhCn, // 使用中文语言
});

// 注册所有图标
for (const [key, component] of Object.entries(ElementPlusIconsVue)) {
  app.component(key, component);
}

// 挂载应用
app.mount("#app");
